WITH metrics AS (SELECT id, session_id, event_type, page, event_time, duration_sec, STDDEV_SAMP(duration_sec) OVER (PARTITION BY session_id) AS session_id_stddev_samp_duration_sec, AVG(duration_sec) OVER (PARTITION BY session_id, page ORDER BY event_time, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS duration_sec_avg_2, AVG(duration_sec) OVER (PARTITION BY page ORDER BY event_time, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS duration_sec_avg_2_2, FIRST_VALUE(page, TRUE) OVER (ORDER BY duration_sec, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_page, SUM(duration_sec) OVER (PARTITION BY page ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_duration_sec FROM web_events WHERE session_id IN (13, 18, 38)) SELECT CASE WHEN duration_sec_avg_2_2 >= 518 THEN 'PREMIUM' ELSE 'STANDARD' END AS duration_sec_avg_2_2_tier, CASE WHEN cumulative_duration_sec >= 2653 THEN 'HIGH' ELSE 'LOW' END AS cumulative_duration_sec_tier, page, PERCENTILE_APPROX(cumulative_duration_sec, 0.95) AS cumulative_duration_sec_p95, COUNT(*) AS num_rows, APPROX_PERCENTILE(duration_sec_avg_2_2, ARRAY(0.25, 0.5, 0.75)) AS duration_sec_avg_2_2_quartiles, COUNT(CASE WHEN event_type = 'search' THEN 1 END) AS search_count FROM metrics GROUP BY CUBE (CASE WHEN duration_sec_avg_2_2 >= 518 THEN 'PREMIUM' ELSE 'STANDARD' END, CASE WHEN cumulative_duration_sec >= 2653 THEN 'HIGH' ELSE 'LOW' END, page) ORDER BY search_count NULLS LAST
